use Filament\Support\Icons\Heroicon;
class SeoSettings extends Page implements HasForms { use InteractsWithForms; protected static string|BackedEnum|null $navigationIcon=Heroicon::MagnifyingGlass; protected static ?string $navigationLabel='SEO وإعدادات الموقع'; protected static ?string $title='SEO وإعدادات الموقع'; protected static ?int $navigationSort=2; protected string $view='filament.admin.pages.seo-settings'; public ?array $data=[]; public static function getNavigationGroup(): ?string { return 'إعدادات والنظام'; } public function mount(): void { abort_unless(auth()->user()->can('settings.show'),403); $settings = Setting::getSettings(); $defaults = ['seo_home_title_ar' => 'مدينة الهواتف - جوالات وإلكترونيات في السعودية', 'seo_home_title_en' => 'City Phones - Phones and Electronics in Saudi Arabia', 'seo_home_description_ar' => 'تسوق أحدث الهواتف والأجهزة الإلكترونية والإكسسوارات في السعودية من مدينة الهواتف.', 'seo_home_description_en' => 'Shop phones, electronics and accessories in Saudi Arabia from City Phones.', 'seo_home_keywords_ar' => 'جوالات، هواتف، إلكترونيات، السعودية، مدينة الهواتف', 'seo_home_keywords_en' => 'phones, electronics, Saudi Arabia, City Phones']; $this->form->fill(array_merge($defaults, array_filter($settings->only($this->fields()), fn ($value) => filled($value)))); } public function getTechnicalScoreProperty(): int { $d = $this->data ?? []; $checks = [filled($d['seo_home_title_ar'] ?? null), filled($d['seo_home_title_en'] ?? null), filled($d['seo_home_description_ar'] ?? null), filled($d['seo_home_description_en'] ?? null), filled($d['seo_home_keywords_ar'] ?? null), filled($d['seo_home_keywords_en'] ?? null), filled($d['seo_og_image'] ?? null), filled($d['seo_business_name_ar'] ?? null)]; return (int) round((count(array_filter($checks)) / count($checks)) * 100); } public function form(Schema $schema): Schema { return $schema->components([Section::make('الصفحة الرئيسية')->description('بيانات Google ونتائج المشاركة. أنشئها بالذكاء الاصطناعي ثم عدّلها عند الحاجة.')->schema([TextInput::make('seo_home_title_ar')->label('عنوان الصفحة الرئيسية بالعربية')->maxLength(70),TextInput::make('seo_home_title_en')->label('عنوان الصفحة الرئيسية بالإنجليزية')->maxLength(70),Textarea::make('seo_home_description_ar')->label('وصف الصفحة الرئيسية بالعربية')->rows(3)->maxLength(170),Textarea::make('seo_home_description_en')->label('وصف الصفحة الرئيسية بالإنجليزية')->rows(3)->maxLength(170),TextInput::make('seo_home_keywords_ar')->label('كلمات مفتاحية بالعربية')->maxLength(500),TextInput::make('seo_home_keywords_en')->label('كلمات مفتاحية بالإنجليزية')->maxLength(500)])->columns(2),Section::make('الهوية والمشاركة')->schema([TextInput::make('seo_business_name_ar')->label('اسم النشاط بالعربية'),TextInput::make('seo_business_name_en')->label('اسم النشاط بالإنجليزية'),FileUpload::make('seo_og_image')->label('صورة المشاركة Facebook / X')->image()->directory('settings/seo')->helperText('يفضل 1200 × 630 بكسل.'),TextInput::make('seo_facebook_url')->label('رابط Facebook')->url(),TextInput::make('seo_instagram_url')->label('رابط Instagram')->url(),TextInput::make('seo_x_url')->label('رابط X')->url()])->columns(2)])->statePath('data'); } public function generate(): void { try { $this->data=array_merge($this->data ?? [],app(SiteSeoAiService::class)->generate()); $this->form->fill($this->data); Notification::make()->title('تم إنشاء مسودة SEO بالذكاء الاصطناعي')->success()->send(); } catch (\Throwable $e) { report($e); Notification::make()->title('تعذر إنشاء SEO')->body($e->getMessage())->danger()->send(); } } public function save(): void { abort_unless(auth()->user()->can('settings.update'),403); Setting::getSettings()->update($this->form->getState()); Notification::make()->title('تم حفظ إعدادات SEO')->success()->send(); } private function fields(): array { return ['seo_home_title_ar','seo_home_title_en','seo_home_description_ar','seo_home_description_en','seo_home_keywords_ar','seo_home_keywords_en','seo_og_image','seo_business_name_ar','seo_business_name_en','seo_facebook_url','seo_instagram_url','seo_x_url']; } }